// generated by gemini-3.5-flash-lite for PR #5883 (round 1): gen_24
// intent: Exercises vector-based plain short string copy paths and short string max optimizations by dumping strings of varying small lengths.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        for (std::size_t len = 1; len <= 32; ++len) {
            std::string s(len, 'a');
            nlohmann::json j = s;
            std::string d = j.dump();
            std::cout << len << ": " << d.length() << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
